 $("#workshop-stock-title").textContent="Stock de "+activeWorkshop;const filteredParts=products.filter(p=>!workshopSearch||[p.name,p.sku,p.category].some(v=>v.toLowerCase().includes(workshopSearch.toLowerCase())));
