 const units=products.reduce((n,p)=>n+stockAt(p,activeWorkshop),0);$("#workshop-sku-count").textContent=products.filter(p=>stockAt(p,activeWorkshop)>0).length+" referencias con stock";$("#workshop-empty").hidden=!!filteredParts.length;$(".workshop-table-wrap").style.display=filteredParts.length?"":"none";$("#workshop-showing-label").textContent="Mostrando "+filteredParts.length+" de "+products.length+" repuestos";$("#workshop-total-label").textContent=units.toLocaleString("es-UY")+" unidades en "+activeWorkshop;$("#workshop-clear").hidden=!workshopSearch
