function exportCsv(filename,header,values){const lines=[header,...values].map(row=>row.map(v=>'"'+String(v??"").replace(/"/g,'""')+'"').join(";")),blob=new Blob([String.fromCharCode(65279)+lines.join(String.fromCharCode(13,10))],{type:"text/csv;charset=utf-8"}),a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download=filename;a.click();URL.revokeObjectURL(a.href)}
