async function exportXlsx(filename,title,columns,data){const workbook=new ExcelJS.Workbook();workbook.creator="Nexo Stock";workbook.created=new Date();const sheet=workbook.addWorksheet(title,{views:[{state:"frozen",ySplit:4}]});sheet.columns=columns.map(c=>({width:c.width||18}));sheet.mergeCells(1,1,1,columns.length);const titleCell=sheet.getCell(1,1);titleCell.value="NEXO STOCK  ·  "+title.toUpperCase();titleCell.fill={type:"pattern",pattern:"solid",fgColor:{argb:"FFC4611C"}};titleCell.font={name:"Aptos",size:16,bold:true,color:{argb:"FFFFFFFF"}};titleCell.alignment={vertical:"middle"};sheet.getRow(1).height=32;sheet.mergeCells(2,1,2,columns.length);sheet.getCell(2,1).value="Exportado el "+new Intl.DateTimeFormat("es-UY",{dateStyle:"long",timeStyle:"short"}).format(new Date());sheet.getCell(2,1).font={name:"Aptos",size:10,color:{argb:"FF665B52"}};sheet.getRow(2).height=22;sheet.getRow(4).values=columns.map(c=>c.header);const header=sheet.getRow(4);header.height=26;header.eachCell(cell=>{cell.fill={type:"pattern",pattern:"solid",fgColor:{argb:"FFFFE9D6"}};cell.font={name:"Aptos",size:10,bold:true,color:{argb:"FF7D3B0F"}};cell.alignment={vertical:"middle",wrapText:true};cell.border={bottom:{style:"medium",color:{argb:"FFE28E43"}}}});data.forEach((values,i)=>{const row=sheet.getRow(i+5);row.values=values;row.height=22;row.eachCell((cell,col)=>{cell.font={name:"Aptos",size:10,color:{argb:"FF292521"}};cell.alignment={vertical:"middle",wrapText:true};cell.fill={type:"pattern",pattern:"solid",fgColor:{argb:i%2?"FFFFFAF5":"FFFFFFFF"}};cell.border={bottom:{style:"hair",color:{argb:"FFF0E8E0"}}};if(typeof cell.value==="number")cell.numFmt=col===9&&title==="Inventario de repuestos"?'"$" #,##0':'#,##0.##'});const statusIndex=columns.findIndex(c=>c.key==="status");if(statusIndex>=0){const cell=row.getCell(statusIndex+1),value=String(cell.value||"");if(value==="Agotado"){cell.font={name:"Aptos",size:10,bold:true,color:{argb:"FFB64E45"}};cell.fill={type:"pattern",pattern:"solid",fgColor:{argb:"FFFFEFED"}}}else if(value==="Stock bajo"){cell.font={name:"Aptos",size:10,bold:true,color:{argb:"FFAE681B"}};cell.fill={type:"pattern",pattern:"solid",fgColor:{argb:"FFFFF3E5"}}}}});if(data.length)sheet.autoFilter={from:{row:4,column:1},to:{row:4+data.length,column:columns.length}};sheet.views=[{state:"frozen",ySplit:4}];const buffer=await workbook.xlsx.writeBuffer();downloadFile(new Blob([buffer],{type:"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"}),filename)}
function exportPdf(filename,title,columns,data,summary=[]){const {jsPDF}=window.jspdf,doc=new jsPDF({orientation:"landscape",unit:"mm",format:"a4"}),pageWidth=doc.internal.pageSize.getWidth(),pageHeight=doc.internal.pageSize.getHeight(),margin=12,contentWidth=pageWidth-margin*2,weights=columns.map(c=>c.width||1),totalWeight=weights.reduce((a,b)=>a+b,0),widths=weights.map(w=>contentWidth*w/totalWeight);let y=34,page=1;const drawTop=()=>{doc.setFillColor(196,97,28);doc.rect(0,0,pageWidth,25,"F");doc.setTextColor(255,255,255);doc.setFont("helvetica","bold");doc.setFontSize(15);doc.text("NEXO STOCK  ·  "+title,margin,11);doc.setFont("helvetica","normal");doc.setFontSize(8);doc.text("Exportado el "+new Intl.DateTimeFormat("es-UY",{dateStyle:"long",timeStyle:"short"}).format(new Date()),margin,18)};const drawColumns=()=>{let x=margin;doc.setFillColor(255,233,214);doc.rect(margin,y,contentWidth,10,"F");doc.setFont("helvetica","bold");doc.setFontSize(7.5);doc.setTextColor(125,59,15);columns.forEach((c,i)=>{doc.text(doc.splitTextToSize(c.header,widths[i]-3).slice(0,2),x+1.5,y+4,{lineHeightFactor:1.05});x+=widths[i]});y+=10};drawTop();if(summary.length){const cellWidth=contentWidth/2,rowHeight=14;summary.forEach((item,index)=>{const column=index%2,row=Math.floor(index/2);if(column===0){doc.setFillColor(255,250,245);doc.rect(margin,29+row*rowHeight,contentWidth,rowHeight-1,"F")}const x=margin+column*cellWidth+3,top=31+row*rowHeight;doc.setTextColor(125,59,15);doc.setFont("helvetica","bold");doc.setFontSize(6);doc.text(item.name,x,top);doc.setFontSize(8);doc.text(doc.splitTextToSize(String(item.value),cellWidth-6)[0],x+cellWidth*.46,top,{maxWidth:cellWidth*.5});doc.setTextColor(100,93,86);doc.setFont("helvetica","normal");doc.setFontSize(5.5);doc.text(doc.splitTextToSize(item.note,cellWidth-6).slice(0,2),x,top+4,{lineHeightFactor:1.1})});y=29+Math.ceil(summary.length/2)*rowHeight+3}drawColumns();data.forEach((row,index)=>{const cells=row.map((v,i)=>doc.splitTextToSize(String(v??"—"),Math.max(8,widths[i]-3)).slice(0,2)),height=Math.max(8,cells.reduce((n,a)=>Math.max(n,a.length),1)*3.5+2);if(y+height>pageHeight-14){page++;doc.addPage();drawTop();y=29;drawColumns()}if(index%2===1){doc.setFillColor(255,250,245);doc.rect(margin,y,contentWidth,height,"F")}let x=margin;doc.setFont("helvetica","normal");doc.setFontSize(7);doc.setTextColor(41,37,33);cells.forEach((lines,i)=>{doc.text(lines,x+1.5,y+4,{lineHeightFactor:1.05});x+=widths[i]});doc.setDrawColor(240,232,224);doc.line(margin,y+height,margin+contentWidth,y+height);y+=height});for(let i=1;i<=page;i++){doc.setPage(i);doc.setFont("helvetica","normal");doc.setFontSize(7);doc.setTextColor(110,101,93);doc.text("Nexo Stock  ·  Página "+i+" de "+page,pageWidth-margin,pageHeight-6,{align:"right"})}doc.save(filename)}
const URUGUAY_TIMEZONE="America/Montevideo";
function updateTopbarClock(){const now=new Date();$("#live-clock").textContent=new Intl.DateTimeFormat("es-UY",{timeZone:URUGUAY_TIMEZONE,hour:"2-digit",minute:"2-digit",second:"2-digit",hour12:false}).format(now);$("#today").textContent=new Intl.DateTimeFormat("es-UY",{timeZone:URUGUAY_TIMEZONE,day:"numeric",month:"short",year:"numeric"}).format(now)}
function weatherLabel(code){if(code===0)return "Despejado";if(code===1)return "Mayormente despejado";if(code===2)return "Parcialmente nublado";if(code===3)return "Nublado";if([45,48].includes(code))return "Niebla";if([51,53,55,56,57].includes(code))return "Llovizna";if([61,63,65,66,67,80,81,82].includes(code))return "Lluvia";if([71,73,75,77,85,86].includes(code))return "Nieve";if([95,96,99].includes(code))return "Tormenta";return "Tiempo actual"}
function weatherSymbol(code,isDay){if(code===0)return isDay?"☀":"☾";if([1,2].includes(code))return isDay?"⛅":"☁";if(code===3||[45,48].includes(code))return "☁";if([95,96,99].includes(code))return "⛈";if([71,73,75,77,85,86].includes(code))return "❄";return "🌧"}
async function updateBellaUnionWeather(){const url="https://api.open-meteo.com/v1/forecast?latitude=-30.26&longitude=-57.60&current=temperature_2m,apparent_temperature,weather_code,is_day&temperature_unit=celsius&timezone=America%2FMontevideo";try{const response=await fetch(url,{cache:"no-store"});if(!response.ok)throw new Error("weather request failed");const data=await response.json(),current=data.current;if(!current)throw new Error("weather data missing");const description=weatherLabel(current.weather_code);$("#weather-temp").textContent=Math.round(current.temperature_2m)+"°C";$("#weather-description").textContent=description;$("#weather-icon").textContent=weatherSymbol(current.weather_code,current.is_day);$("#weather-widget").title="Bella Unión · "+description+" · Sensación térmica "+Math.round(current.apparent_temperature)+"°C · Actualizado "+new Intl.DateTimeFormat("es-UY",{timeZone:URUGUAY_TIMEZONE,hour:"2-digit",minute:"2-digit"}).format(new Date())}catch(error){$("#weather-temp").textContent="—";$("#weather-description").textContent="Tiempo no disponible";$("#weather-icon").textContent="☁";$("#weather-widget").title="No se pudo consultar el tiempo actual de Bella Unión"}}
updateTopbarClock();setInterval(updateTopbarClock,1000);updateBellaUnionWeather();setInterval(updateBellaUnionWeather,15*60*1000);
