function captureProductBarcode(){const input=$("#product-barcode-scan"),code=input.value.trim(),feedback=$("#product-scan-feedback");input.value="";if(!code){input.focus();return}const owner=findProductCode(code);if(owner){feedback.textContent="Este código ya pertenece a «"+owner.name+"». No se sumó otra unidad.";feedback.className="scan-feedback missing";input.focus();return}if(!productBarcodes.some(value=>value.toLocaleLowerCase()===code.toLocaleLowerCase()))productBarcodes.push(code);productScanCount++;const stock=$("#product-form [name=stock]");stock.value=(Number(stock.value)||0)+1;feedback.textContent="Lectura "+productScanCount+": 1 unidad sumada al stock inicial.";feedback.className="scan-feedback found";renderProductBarcodeBatch();if(productScanCount%appSettings.barcodePromptEvery===0){$("#product-scan-warning-text").textContent="Llevas "+productScanCount+" lecturas de «"+($("#product-form [name=name]").value.trim()||"este repuesto")+"». ¿Sigues con el mismo repuesto o quieres cambiar?";$("#product-scan-warning").hidden=false;input.disabled=true;$("#product-scan-continue").focus();return}input.focus()}
function saveNewProduct(e){e.preventDefault();if(!canWrite())return;const data=new FormData(e.currentTarget),name=String(data.get("name")||"").trim(),sku=String(data.get("sku")||"").trim(),newCategory=String(data.get("category")||"").trim(),supplier=String(data.get("supplier")||"").trim(),count=Number(data.get("stock")),minimum=Number(data.get("min")),cost=Number(data.get("cost")),site=String(data.get("warehouse"));$("#product-form-error").hidden=true;if(findProductCode(sku)){$("#product-form-error").textContent="Ese SKU ya existe en Inventario. Registra una entrada de stock sobre el repuesto existente.";$("#product-form-error").hidden=false;return}if(products.some(p=>String(p.name||"").trim().toLocaleLowerCase()===name.toLocaleLowerCase()&&String(p.category||"").trim().toLocaleLowerCase()===newCategory.toLocaleLowerCase())){$("#product-form-error").textContent="Ya existe un repuesto con ese nombre y categoría. Búscalo en Inventario y registra una entrada para sumar stock.";$("#product-form-error").hidden=false;return}const conflictingCode=productBarcodes.find(code=>findProductCode(code));if(conflictingCode){$("#product-form-error").textContent="El código «"+conflictingCode+"» ya está asignado a otro repuesto.";$("#product-form-error").hidden=false;return}const p={id:Math.max(0,...products.map(x=>Number(x.id)||0))+1,name,sku,barcode:productBarcodes[0]||"",barcodes:[...productBarcodes],category:newCategory,stock:count,min:minimum,cost,supplier,warehouse:site,workshopStock:{"Bella Unión":0,"Montevideo":0},storageByWorkshop:{"Bella Unión":{cabinet:"",space:""},"Montevideo":{cabinet:"",space:""}}};p.workshopStock[site]=count;p.stock=count;products.push(p);if(supplier)ensureSupplierRecord(supplier);if(count>0){const id="MOV-"+String(Date.now()).slice(-6);movements.unshift({id,type:"entrada",productId:p.id,quantity:count,delta:count,unitCost:Number(p.cost)||0,supplier,fromStock:0,toStock:count,workshopFromStock:0,workshopToStock:count,warehouse:site,destination:"",reference:id,reason:"Inventario inicial",note:"Stock inicial al registrar el repuesto. Unidades escaneadas: "+productScanCount+".",date:new Date().toISOString(),user:currentUser().name})}const nextProduct=queueNextProduct;saveProducts();saveMovements();renderInventory();renderWorkshops();renderMovements();renderVehicles();renderDashboard();closeProductModal();logActivity("Repuesto creado",name+" · SKU "+sku+" · "+productScanCount+" lecturas · "+productBarcodes.length+" códigos distintos · Categoría "+newCategory);notify("Repuesto registrado en la categoría «"+newCategory+"».");if(nextProduct)setTimeout(openProductModal,120)}
