$("#movement-form").addEventListener("submit",e=>{
 e.preventDefault();if(!canWrite())return;const data=new FormData(e.currentTarget),p=products.find(x=>x.id===Number(data.get("product"))),qty=Number(data.get("quantity")),type=data.get("type"),source=String(data.get("warehouse")),destination=String(data.get("destination")||""),vehicleId=String(data.get("vehicleId")||""),supplierName=String(data.get("supplier")||"").trim(),purchaseCost=Number(data.get("purchaseCost"));
 if(!p||qty<1)return;
 if(type==="entrada"&&(String(data.get("reason")||"")!=="Compra a proveedor"||!supplierName||!Number.isFinite(purchaseCost)||purchaseCost<0)){$("#form-error").textContent="Para ingresar stock, registra una compra a proveedor con proveedor y costo válidos." ;$("#form-error").hidden=false;return}
 if(type==="salida"&&!VEHICLES.includes(vehicleId)){$("#form-error").textContent="Selecciona el coche que recibirá el repuesto.";$("#form-error").hidden=false;return}
 const beforeGlobal=totalStock(p),beforeSource=stockAt(p,source);let afterSource=beforeSource,afterDestination=destination?stockAt(p,destination):0,delta=0;
 if(type==="traslado"){
  if(source===destination){$("#form-error").textContent="Elige dos talleres diferentes para el traslado.";$("#form-error").hidden=false;return}
  if(beforeSource<qty){$("#form-error").textContent="No hay suficiente stock en "+source+" para trasladar esa cantidad." ;$("#form-error").hidden=false;return}
  afterSource=beforeSource-qty;afterDestination+=qty;p.workshopStock[source]=afterSource;p.workshopStock[destination]=afterDestination;
 }else if(type==="salida"){
  if(beforeSource<qty){$("#form-error").textContent="No hay suficiente stock en "+source+" para registrar esta salida." ;$("#form-error").hidden=false;return}
  afterSource=beforeSource-qty;p.workshopStock[source]=afterSource;delta=-qty;
 }else if(type==="ajuste"){
  afterSource=qty;p.workshopStock[source]=afterSource;delta=qty-beforeSource;
 }else{afterSource=beforeSource+qty;p.workshopStock[source]=afterSource;delta=qty}
 const afterGlobal=totalStock(p),date=new Date(data.get("movementDate"));
 if(Number.isNaN(date.getTime())){$("#form-error").textContent="Indica una fecha y hora válidas." ;$("#form-error").hidden=false;return}
 const storageCabinet=String(data.get("storageCabinet")||"").trim(),storageSpace=String(data.get("storageSpace")||"").trim();p.storageByWorkshop[source]={cabinet:storageCabinet,space:storageSpace};p.stock=afterGlobal;p.warehouse=type==="traslado"?destination:source;if(type==="entrada"){p.supplier=supplierName;p.cost=purchaseCost}
 const id="MOV-"+String(Date.now()).slice(-6),note=String(data.get("note")||"").trim(),reference=String(data.get("reference")||"").trim()||id,reason=String(data.get("reason")||""),breakdownType=String(data.get("breakdownType")||""),breakdownOther=String(data.get("breakdownOther")||"").trim();
 movements.unshift({id,type,productId:p.id,quantity:qty,delta,unitCost:type==="entrada"?purchaseCost:Number(p.cost)||0,supplier:type==="entrada"?supplierName:"",storageLocation:{cabinet:storageCabinet,space:storageSpace},breakdownType,breakdownOther,vehicleId:type==="salida"?vehicleId:"",fromStock:beforeGlobal,toStock:afterGlobal,workshopFromStock:beforeSource,workshopToStock:afterSource,destination: type==="traslado"?destination:"",destinationFromStock:type==="traslado"?afterDestination-qty:0,destinationToStock:type==="traslado"?afterDestination:0,warehouse:source,reference,reason,note,date:date.toISOString(),user:currentUser().name});
 saveProducts();saveMovements();renderInventory();renderWorkshops();renderDashboard();if(!$("#movements-page").hidden)renderMovements();if(!$("#vehicles-page").hidden)renderVehicles();logActivity("Movimiento registrado",({entrada:"Entrada",salida:"Salida",ajuste:"Ajuste",traslado:"Traslado"}[type]||type)+" · "+p.name+" · "+qty+" ud. · "+source+(vehicleId?" · "+vehicleId:""));closeModal();e.currentTarget.reset();notify(type==="traslado"?"Traslado registrado · "+qty+" unidades de "+source+" a "+destination+".":type==="salida"?"Repuesto asignado a "+vehicleId+" · "+p.name+".":"Movimiento guardado · "+p.name+" ahora tiene "+afterGlobal+" unidades en total.")
});
