function getMovementExportData(){const type=$("#movement-type-filter").value,store=$("#movement-warehouse-filter").value,q=$("#movement-search").value.trim().toLowerCase(),cutoff=Date.now()-30*86400000,list=movements.filter(m=>{const p=products.find(x=>x.id===m.productId)||{};return new Date(m.date).getTime()>=cutoff&&(!type||m.type===type)&&(!store||m.warehouse===store||m.destination===store)&&(!q||[m.id,m.reference,p.name,p.sku,m.note,m.destination,m.vehicleId].some(v=>String(v||"").toLowerCase().includes(q)))});return list.map(m=>{const p=products.find(x=>x.id===m.productId)||{};return[m.id,new Date(m.date).toLocaleString("es-UY"),m.type,p.name||"",p.sku||"",m.warehouse,m.storageLocation?.cabinet||storageFor(p,m.warehouse).cabinet||"—",m.storageLocation?.space||storageFor(p,m.warehouse).space||"—",m.destination||"—",m.vehicleId||"—",m.supplier||"—",Number(m.unitCost)||0,Number(m.delta)||0,Number(m.toStock)||0,m.reference||"",m.user||"Lucía Martínez"]})}
